            margin: 0;
        }}
    </style>
</head>
<body>

    <header>
        <h1>Global Intentional Homicide Trends (1990–2023)</h1>
        <p class="one-liner">A comprehensive trend analysis of intentional homicide rates across countries, sexes, and age groups over three decades, drawing on UNODC data.</p>
    </header>

    <div class="dashboard">
        <div class="kpi-card">
            <div class="kpi-title">Global Median Rate</div>
            <div class="kpi-value">{global_median:.2f}</div>
            <div class="kpi-desc">per 100k (Most Recent Year)</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-title">Male/Female Ratio</div>
            <div class="kpi-value">{m_f_ratio:.1f}x</div>
            <div class="kpi-desc">Global Disparity</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-title">Peak National Rate</div>
            <div class="kpi-value">{highest_country['homicide_rate']:.1f}</div>
            <div class="kpi-desc">{highest_country['country']}</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-title">2010s vs 2020s Change</div>
            <div class="kpi-value">{dec_change:+.1f}%</div>
            <div class="kpi-desc">Global Average Trajectory</div>
